88	    public OwnerRestControllerV1(ClinicService clinicService,
89	                                 OwnerMapper ownerMapper,
90	                                 PetMapper petMapper,
91	                                 VisitMapper visitMapper,
92	                                 TelephoneNormalizer telephoneNormalizer,
93	                                 AddressNormalizer addressNormalizer,
94	                                 EmailNormalizer emailNormalizer) {
95	        this.clinicService = clinicService;
96	        this.ownerMapper = ownerMapper;
97	        this.petMapper = petMapper;
98	        this.visitMapper = visitMapper;
99	        this.telephoneNormalizer = telephoneNormalizer;
100	        this.addressNormalizer = addressNormalizer;
101	        this.emailNormalizer = emailNormalizer;
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
107	        Collection<Owner> owners;
108	        if (lastName != null) {
109	            owners = this.clinicService.findOwnerByLastName(lastName);
110	        } else {
111	            owners = this.clinicService.findAllOwners();
112	        }
113	        if (owners.isEmpty()) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
122	        Owner owner = this.clinicService.findOwnerById(ownerId);
123	        if (owner == null) {
124	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
125	        }
126	        return new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
132	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
133	        rejectBlankOwnerFields(ownerFieldsDto);
134	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
135	        if (!sharesHousehold) {
136	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
137	        }
138	        rejectCityAtCapacity(ownerFieldsDto.getCity());
139	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
140	        rejectDailyRegistrationLimit(registrationDate);
141	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
142	        rejectDuplicateTelephone(normalizedTelephone);
143	        ownerFieldsDto.setTelephone(normalizedTelephone);
144	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
145	        rejectDuplicateEmail(normalizedEmail);
146	        ownerFieldsDto.setEmail(normalizedEmail);
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        owner.setRegistrationDate(registrationDate);
150	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
151	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
152	        if (sharesHousehold) {
153	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
154	        }
155	        this.clinicService.saveOwner(owner);
156	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
157	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
158	            ownerMapper.membershipLevel(owner));
159	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
160	        headers.setLocation(UriComponentsBuilder.newInstance()
161	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
162	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
168	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
169	        if (currentOwner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        currentOwner.setAddress(ownerFieldsDto.getAddress());
173	        currentOwner.setCity(ownerFieldsDto.getCity());
174	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
175	        currentOwner.setLastName(ownerFieldsDto.getLastName());
176	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
177	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
178	        this.clinicService.saveOwner(currentOwner);
179	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Transactional
184	    @Override
185	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
186	        Owner owner = this.clinicService.findOwnerById(ownerId);
187	        if (owner == null) {
188	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
189	        }
190	        this.clinicService.deleteOwner(owner);
191	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
192	    }
