213	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
214	    @Override
215	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
216	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
217	        if (currentOwner != null) {
218	            Pet currentPet = this.clinicService.findPetById(petId);
219	            if (currentPet != null) {
220	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
221	                currentPet.setName(petFieldsDto.getName());
222	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
223	                this.clinicService.savePet(currentPet);
224	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
225	            }
226	        }
227	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
228	    }
