246	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
247	    @Override
248	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
249	        Owner owner = this.clinicService.findOwnerById(ownerId);
250	        if (owner != null) {
251	            Pet pet = owner.getPet(petId);
252	            if (pet != null) {
253	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
254	            }
255	        }
256	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
257	    }
258	
259	    /**
260	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
261	     * derived from server-side state rather than stored columns (currently the
262	     * {@code bulkSignupWarning} flag). Both the create endpoint and the single-owner read endpoint
263	     * return their owner through this method, so an owner is decorated identically on either path
264	     * and each derived field is computed in exactly one place.
265	     *
266	     * @param owner the persisted owner to represent
267	     * @return the owner DTO with its derived read-only fields populated
268	     */
269	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
270	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
271	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
272	        return ownerDto;
273	    }
274	
275	    /**
276	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
277	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
278	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
279	     * blank (e.g. {@code "   "}). The offending field names are reported through an
280	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
281	     * as a 400 response carrying an {@code errors} array of field names.
282	     *
283	     * @param ownerFieldsDto the submitted owner fields
284	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
285	     */
286	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
287	        List<String> blankFields = new ArrayList<>();
288	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
289	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
290	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
291	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
292	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
293	        if (!blankFields.isEmpty()) {
294	            throw new InvalidOwnerFieldsException(blankFields);
295	        }
296	    }
297	
298	    private void addIfBlank(List<String> blankFields, String field, String value) {
299	        if (value != null && value.isBlank()) {
300	            blankFields.add(field);
301	        }
302	    }
303	
304	    /**
305	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
306	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
307	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
308	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
309	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
310	     *
311	     * @param city the city of the owner being created
312	     * @param lastName the last name of the owner being created
313	     * @return the formatted customer code
314	     */
315	    private String nextCustomerCode(String city, String lastName) {
316	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
317	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
318	        long sequence = this.clinicService.findAllOwners().stream()
319	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
320	            .count() + 1L;
321	        return String.format("%s-%s-%04d", city3, last3, sequence);
322	    }
323	
324	    /**
325	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
326	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
327	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
328	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
329	     * new owner and surfaced as the read-only {@code namesakeCount} field.
330	     *
331	     * @param firstName the first name of the owner being created
332	     * @param lastName the last name of the owner being created
333	     * @return the number of existing owners with the same first and last name (case-insensitive)
334	     */
335	    private int namesakeCount(String firstName, String lastName) {
336	        return (int) this.clinicService.findAllOwners().stream()
337	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
338	                && equalsIgnoreCase(owner.getLastName(), lastName))
339	            .count();
340	    }
341	
342	    private boolean equalsIgnoreCase(String a, String b) {
343	        return a == null ? b == null : a.equalsIgnoreCase(b);
344	    }
345	
346	    /**
347	     * The maximum number of owners a single city may contain. Once a city already holds this many
348	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
349	     */
350	    private static final long MAX_OWNERS_PER_CITY = 50L;
351	
352	    /**
353	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
354	     * owners. Existing owners are matched to the requested city case-insensitively (using
355	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
356	     * the per-city counting used for the customer code. A city at capacity is reported through an
357	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
358	     * 409 Conflict response.
359	     *
360	     * @param city the city of the owner being created
361	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
362	     */
363	    private void rejectCityAtCapacity(String city) {
364	        long owners = this.clinicService.findAllOwners().stream()
365	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
366	            .count();
367	        if (owners >= MAX_OWNERS_PER_CITY) {
368	            throw new OwnerCityAtCapacityException(city);
369	        }
370	    }
371	
372	    /**
373	     * The maximum number of owners that may be registered on a single day. Once this many owners
374	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
375	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
376	     */
377	    private static final long MAX_OWNERS_PER_DAY = 100L;
378	
379	    /**
380	     * Resolves the effective registration date for a create request: the value supplied in the
381	     * request when present, otherwise the server's current date. The result is the raw effective
382	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
383	     *
384	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
385	     * @return the supplied date, or today when none was supplied
386	     */
387	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
388	        return suppliedDate != null ? suppliedDate : LocalDate.now();
389	    }
390	
391	    /**
392	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
393	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
394	     * the effective registration date so that a weekend value - whether supplied in the request or
395	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
396	     * registration date (such as the membership number's year segment and the daily create-limit
397	     * bucket) uses the adjusted business day.
398	     *
399	     * @param date the effective registration date
400	     * @return the same date when it is a weekday, otherwise the next Monday
401	     */
402	    private LocalDate businessDay(LocalDate date) {
403	        DayOfWeek dayOfWeek = date.getDayOfWeek();
404	        if (dayOfWeek == DayOfWeek.SATURDAY) {
405	            return date.plusDays(2);
406	        }
407	        if (dayOfWeek == DayOfWeek.SUNDAY) {
408	            return date.plusDays(1);
409	        }
410	        return date;
411	    }
412	
413	    /**
414	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
415	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
416	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
417	     * renders as a 429 Too Many Requests response.
418	     *
419	     * @param date the registration date of the owner being created (today)
420	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
421	     */
422	    private void rejectDailyRegistrationLimit(LocalDate date) {
423	        long owners = this.clinicService.findAllOwners().stream()
424	            .filter(owner -> date.equals(owner.getRegistrationDate()))
425	            .count();
426	        if (owners >= MAX_OWNERS_PER_DAY) {
427	            throw new DailyOwnerRegistrationLimitException(date);
428	        }
429	    }
430	
431	    /**
432	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
433	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
434	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
435	     */
436	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
437	
438	    /**
439	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
440	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
441	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
442	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
443	     * without a registration date, such as seed data) is never flagged.
444	     *
445	     * @param date the owner's registration date (the day it was created), or {@code null}
446	     * @return {@code true} if the day already holds more than the warning threshold of owners
447	     */
448	    private boolean bulkSignupWarning(LocalDate date) {
449	        if (date == null) {
450	            return false;
451	        }
452	        long owners = this.clinicService.findAllOwners().stream()
453	            .filter(owner -> date.equals(owner.getRegistrationDate()))
454	            .count();
455	        return owners > BULK_SIGNUP_WARNING_THRESHOLD;
456	    }
457	
458	    /**
459	     * Rejects a create request whose normalized telephone is already used by any existing owner.
460	     * Existing owners' telephones are reduced to the same canonical form (via
461	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
462	     * only in formatting still collide. A collision is reported through a
463	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
464	     * as a 409 Conflict response.
465	     *
466	     * @param normalizedTelephone the canonical telephone of the owner being created
467	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
468	     */
469	    private void rejectDuplicateTelephone(String normalizedTelephone) {
470	        boolean duplicate = existingOwnerMatches(
471	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
472	            normalizedTelephone);
473	        if (duplicate) {
474	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
475	        }
476	    }
477	
478	    /**
479	     * Rejects a create request whose normalized (lower-cased) email is already used by any existing
480	     * owner. Existing owners' emails are reduced to the same canonical form (via
481	     * {@link EmailNormalizer#normalize(String)}, i.e. lower-cased) before comparison, so addresses
482	     * that differ only in casing still collide. Owners without an email are ignored, and a request
483	     * without an email is never rejected. A collision is reported through a
484	     * {@link DuplicateOwnerEmailException}, which the {@code ExceptionControllerAdvice} renders as a
485	     * 409 Conflict response.
486	     *
487	     * @param normalizedEmail the canonical (lower-cased) email of the owner being created, or
488	     * {@code null} when none was supplied
489	     * @throws DuplicateOwnerEmailException if another owner already uses this email
490	     */
491	    private void rejectDuplicateEmail(String normalizedEmail) {
492	        if (normalizedEmail == null) {
493	            return;
494	        }
495	        boolean duplicate = existingOwnerMatches(
496	            owner -> emailNormalizer.normalize(owner.getEmail()),
497	            normalizedEmail);
498	        if (duplicate) {
499	            throw new DuplicateOwnerEmailException(normalizedEmail);
500	        }
501	    }
502	
503	    /**
504	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
505	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
506	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
507	     * and the owner being created to the same canonical key and reject a match.
508	     *
509	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
510	     * @param key the canonical key of the owner being created
511	     * @return {@code true} if some existing owner shares the key
512	     */
513	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
514	        return this.clinicService.findAllOwners().stream()
515	            .map(keyExtractor)
516	            .filter(Objects::nonNull)
517	            .anyMatch(key::equals);
518	    }
519	
520	    /**
521	     * Rejects a create request that shares a household with an existing owner: another owner already
522	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
523	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
524	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
525	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
526	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
527	     * check when the request opts in via {@code sharesHousehold}.
528	     *
529	     * @param lastName the last name of the owner being created
530	     * @param address the address of the owner being created
531	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
532	     */
533	    private void rejectDuplicateHousehold(String lastName, String address) {
534	        String canonicalLastName = canonicalizeHousehold(lastName);
535	        String canonicalAddress = canonicalizeHousehold(address);
536	        String key = householdKey(lastName, address);
537	        if (key == null) {
538	            return;
539	        }
540	        boolean duplicate = existingOwnerMatches(
541	            owner -> householdKey(owner.getLastName(), owner.getAddress()), key);
542	        if (duplicate) {
543	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
544	        }
545	    }
546	
547	    /**
548	     * Delimiter joining the canonical household fields into a single comparison key. A run of
549	     * whitespace is collapsed to a single space by {@link #canonicalizeHousehold(String)}, so this
550	     * newline can never occur inside a canonical value and the two fields cannot bleed into one
551	     * another across the join.
552	     */
553	    private static final String HOUSEHOLD_KEY_DELIMITER = "\n";
554	
555	    /**
556	     * Reduces an owner's household fields ({@code lastName} and {@code address}) to a single
557	     * canonical comparison key - the two canonical fields (see {@link #canonicalizeHousehold(String)})
558	     * joined by {@link #HOUSEHOLD_KEY_DELIMITER} - or {@code null} when either field is absent. Two
559	     * owners share a household exactly when their household keys are equal, so
560	     * {@link #rejectDuplicateHousehold(String, String)} can detect a collision by comparing this one
561	     * key through {@link #existingOwnerMatches(Function, String)} rather than the two fields separately.
562	     *
563	     * @param lastName the owner's last name, or {@code null}
564	     * @param address the owner's address, or {@code null}
565	     * @return the canonical household key, or {@code null} when either field is {@code null}
566	     */
567	    private String householdKey(String lastName, String address) {
568	        String canonicalLastName = canonicalizeHousehold(lastName);
569	        String canonicalAddress = canonicalizeHousehold(address);
570	        if (canonicalLastName == null || canonicalAddress == null) {
571	            return null;
572	        }
573	        return canonicalLastName + HOUSEHOLD_KEY_DELIMITER + canonicalAddress;
574	    }
575	
576	    /**
577	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
578	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
579	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
580	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
581	     *
582	     * @param value the raw field value, or {@code null}
583	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
584	     */
585	    private String canonicalizeHousehold(String value) {
586	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
587	    }
588	
589	    /**
590	     * Derives the stable, shared {@code householdId} for an owner joining a household via
591	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
592	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
593	     * owner with the same last name at the same address - regardless of casing or spacing - is
594	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
595	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
596	     *
597	     * @param lastName the last name of the owner being created
598	     * @param address the address of the owner being created
599	     * @return the shared household identifier
600	     */
601	    private String householdId(String lastName, String address) {
602	        String key = canonicalizeHousehold(lastName) + "\n" + canonicalizeHousehold(address);
603	        try {
604	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
605	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
606	            StringBuilder sb = new StringBuilder(digest.length * 2);
607	            for (byte b : digest) {
608	                sb.append(String.format("%02X", b));
609	            }
610	            return sb.substring(0, 16);
611	        } catch (java.security.NoSuchAlgorithmException e) {
612	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
613	        }
614	    }
615	}
